const { chatInput, sessionId } = $('Edit Fields').first().json;

// ── Contexte Kayvila ──
let contextData = {};
try {
  contextData = $('Fetch Visitor Context').first().json.context || {};
} catch {}

const villas = contextData.villas || [];
const availableAmenities = contextData.availableAmenities || [];
const villaCount = contextData.villaCount || villas.length;
const conciergerieFacts = contextData.conciergerieFacts || {};

// ── Formatage du menu villas pour le prompt ──
let villasText = '';
if (villas.length > 0) {
  villasText = '🏡 VILLAS DISPONIBLES :\n' + villas.map(v => {
    let line = `• ${v.name || 'Villa'} — ${v.price_per_night || '?'}€/nuit`;
    if (v.bedrooms) line += `, ${v.bedrooms} chambres`;
    if (v.max_guests) line += `, ${v.max_guests} pers. max`;
    if (v.availability) {
      if (v.availability.isAvailableNow) line += ' ✅ DISPONIBLE';
      else if (v.availability.nextAvailableFrom) line += ` 📅 Dispo dès ${v.availability.nextAvailableFrom}`;
      else line += ' 🔒 Complet';
    }
    return line;
  }).join('\n');
} else {
  villasText = 'Aucune villa actuellement disponible.';
}

let amenitiesText = '';
if (availableAmenities.length > 0) {
  amenitiesText = '\n✨ ÉQUIPEMENTS : ' + availableAmenities.slice(0, 20).join(', ');
}

let conciergerieText = '';
if (Object.keys(conciergerieFacts).length > 0) {
  conciergerieText = '\n🎯 CONCIERGERIE : ' + Object.entries(conciergerieFacts).slice(0, 5).map(([k, v]) => `${k}: ${v}`).join(' | ');
}

const systemMessage = `Tu es Kayvibot, l'assistant virtuel de Kayvila — conciergerie de luxe en Martinique. Tu parles français avec élégance et chaleur. Tu es concis, serviable, et tu guides naturellement vers la réservation.

IDENTITÉ
- Conciergerie : Kayvila
- Site web : kayvila.vercel.app
- Localisation : Martinique, Fort-de-France
- Spécialité : villas d'exception avec service conciergerie privé

TON RÔLE
- Aider les visiteurs à trouver la villa parfaite
- Répondre aux questions sur les villas, équipements, disponibilités
- Qualifier les leads (dates, budget, nombre de voyageurs)
- Proposer un pré-booking quand le visiteur est prêt
- Rediriger vers le concierge humain si nécessaire

RÈGLES
- Répondre en JSON avec : reply (texte), stage (greet|discover|qualify|prebook), suggestedQuickReplies (tableau de suggestions)
- Si le visiteur donne dates + villa → proposer pré-booking : { "reply": "...", "stage": "prebook", "preBooking": { "villaId": "...", "startDate": "...", "endDate": "...", "guests": N } }
- Ne JAMAIS inventer de villa ou de disponibilité — utiliser UNIQUEMENT les données du contexte
- Si tu ne sais pas, propose de contacter le concierge humain
- Toujours terminer par une question ouverte ou des quick replies

FORMAT DE RÉPONSE JSON OBLIGATOIRE :
{ "reply": "...", "stage": "...", "suggestedQuickReplies": [...] }

═════════════════════════════
CONTEXTE TEMPS RÉEL :
${villasText}${amenitiesText}${conciergerieText}
═════════════════════════════`;

return {
  json: {
    chatInput,
    sessionId,
    systemMessage,
    contextData
  }
};

const aiResponse =
  $input.first().json.output ||
  $input.first().json.message?.content ||
  $input.first().json.text ||
  '';

let reply = aiResponse;
let stage = 'reply';
let suggestedQuickReplies = [];

// Essayer de parser le JSON
try {
  const parsed = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
  if (parsed && typeof parsed === 'object') {
    reply = parsed.reply || parsed.response || parsed.message || aiResponse;
    stage = parsed.stage || 'reply';
    suggestedQuickReplies = Array.isArray(parsed.suggestedQuickReplies) ? parsed.suggestedQuickReplies : [];
  }
} catch {
  // Réponse texte brute — OK
}

return {
  json: {
    reply,
    stage,
    suggestedQuickReplies,
    rawResponse: aiResponse
  }
};
